    public static string BlogContext(string slug, string culture) =>
        BlogCopy.TryGetValue(slug, out var copy) ? (culture == "en" ? copy.En : copy.Tr) :
        culture == "en" ? "For questions about this guide, contact our salon in Bornova, İzmir. Share the service you are considering and your expectations before arranging a visit." :
        "Bu rehberle ilgili sorularınızı İzmir’in Bornova ilçesindeki salonumuzla paylaşabilirsiniz. Randevu öncesinde düşündüğünüz işlemi ve beklentinizi belirtmeniz, görüşmeyi planlamamıza yardımcı olur.";

    public static string ServiceContext(string slug, string culture) =>
        ServiceCopy.TryGetValue(slug, out var copy) ? (culture == "en" ? copy.En : copy.Tr) :
